-- 审核后在已确认的现有 MySQL schema 显式执行；模块不自动执行迁移。
-- 本脚本仅新增 Paismart 表，不创建数据库或改写平台账户。
CREATE TABLE ps_member (user_id BIGINT PRIMARY KEY, status VARCHAR(16) NOT NULL, membership_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ps_invite (id VARCHAR(36) PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, space_id VARCHAR(36), max_uses INT NOT NULL, used_count INT NOT NULL DEFAULT 0, expires_at TIMESTAMP NULL, enabled BOOLEAN NOT NULL, initial_llm_tokens BIGINT NOT NULL DEFAULT 0, initial_embedding_tokens BIGINT NOT NULL DEFAULT 0, row_version BIGINT NOT NULL DEFAULT 1, created_by BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ps_invite_redemption (id VARCHAR(36) PRIMARY KEY, invite_id VARCHAR(36) NOT NULL, user_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(invite_id,user_id));
CREATE TABLE ps_mutation_request (user_id BIGINT NOT NULL, kind VARCHAR(64) NOT NULL, request_key VARCHAR(128) NOT NULL, input_json TEXT NOT NULL, response_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,kind,request_key));
CREATE TABLE ps_legacy_identity_map (source_user_id VARCHAR(128) PRIMARY KEY, user_id BIGINT NOT NULL, migration_batch_id VARCHAR(64) NOT NULL, source_hash VARCHAR(64) NOT NULL, created_by BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ps_token_account (user_id BIGINT NOT NULL, scope VARCHAR(16) NOT NULL, available BIGINT NOT NULL DEFAULT 0, frozen BIGINT NOT NULL DEFAULT 0, consumed BIGINT NOT NULL DEFAULT 0, debt BIGINT NOT NULL DEFAULT 0, row_version BIGINT NOT NULL DEFAULT 1, PRIMARY KEY(user_id,scope));
CREATE TABLE ps_token_reservation (id VARCHAR(36) PRIMARY KEY, user_id BIGINT NOT NULL, scope VARCHAR(16) NOT NULL, operation_id VARCHAR(160) NOT NULL, mode VARCHAR(16) NOT NULL, reserved_tokens BIGINT NOT NULL, actual_tokens BIGINT NULL, state VARCHAR(16) NOT NULL, business_day DATE NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,scope,operation_id));
CREATE TABLE ps_token_ledger (id VARCHAR(36) PRIMARY KEY, user_id BIGINT NOT NULL, scope VARCHAR(16) NOT NULL, operation_key VARCHAR(192) NOT NULL UNIQUE, action VARCHAR(24) NOT NULL, tokens BIGINT NOT NULL, available_after BIGINT NOT NULL, frozen_after BIGINT NOT NULL, debt_after BIGINT NOT NULL, reason VARCHAR(500) NOT NULL, operator_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_ps_ledger_user_time ON ps_token_ledger(user_id,created_at);
CREATE TABLE ps_daily_usage (user_id BIGINT NOT NULL, business_day DATE NOT NULL, scope VARCHAR(16) NOT NULL, used_tokens BIGINT NOT NULL DEFAULT 0, reserved_tokens BIGINT NOT NULL DEFAULT 0, request_count BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(user_id,business_day,scope));
CREATE TABLE ps_quota_policy (user_id BIGINT PRIMARY KEY, mode VARCHAR(16) NOT NULL, daily_llm_tokens BIGINT NOT NULL DEFAULT 0, daily_embedding_tokens BIGINT NOT NULL DEFAULT 0, row_version BIGINT NOT NULL DEFAULT 1);
CREATE TABLE ps_rate_limit_policy (id INT PRIMARY KEY, chat_per_minute INT NOT NULL, upload_per_minute INT NOT NULL, daily_chat_tokens BIGINT NOT NULL, max_file_bytes BIGINT NOT NULL, rules_json TEXT NULL, row_version BIGINT NOT NULL DEFAULT 1);
CREATE TABLE ps_model_budget_window (budget_kind VARCHAR(32) NOT NULL,window_seconds BIGINT NOT NULL,window_start BIGINT NOT NULL,used_tokens BIGINT NOT NULL DEFAULT 0,reserved_tokens BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(budget_kind,window_seconds,window_start));
CREATE TABLE ps_model_budget_reservation (reservation_id VARCHAR(36) PRIMARY KEY,budget_kind VARCHAR(32) NOT NULL,minute_seconds BIGINT NOT NULL,minute_start BIGINT NOT NULL,day_seconds BIGINT NOT NULL,day_start BIGINT NOT NULL,reserved_tokens BIGINT NOT NULL,actual_tokens BIGINT NULL,state VARCHAR(16) NOT NULL);
CREATE TABLE ps_recharge_package (id VARCHAR(36) PRIMARY KEY, name VARCHAR(128) NOT NULL, amount_fen BIGINT NOT NULL, llm_tokens BIGINT NOT NULL, embedding_tokens BIGINT NOT NULL, description VARCHAR(500) NOT NULL, benefit TEXT NULL, enabled BOOLEAN NOT NULL, sort_order INT NOT NULL DEFAULT 0, deleted BOOLEAN NOT NULL DEFAULT FALSE, row_version BIGINT NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ps_recharge_order (id VARCHAR(36) PRIMARY KEY, user_id BIGINT NOT NULL, request_key VARCHAR(128) NOT NULL, trade_no VARCHAR(64) NOT NULL UNIQUE, package_id VARCHAR(36), snapshot_json TEXT NOT NULL, amount_fen BIGINT NOT NULL, llm_tokens BIGINT NOT NULL, embedding_tokens BIGINT NOT NULL, state VARCHAR(24) NOT NULL, code_url VARCHAR(1024), transaction_id VARCHAR(128) UNIQUE, error_message VARCHAR(500), expires_at TIMESTAMP NOT NULL, paid_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,request_key));
CREATE INDEX idx_ps_order_user_state ON ps_recharge_order(user_id,state,created_at);
CREATE TABLE ps_payment_event (id VARCHAR(36) PRIMARY KEY, event_id VARCHAR(128) NOT NULL UNIQUE, trade_no VARCHAR(64) NOT NULL, transaction_id VARCHAR(128) NOT NULL, amount_fen BIGINT NOT NULL, payload_hash VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ps_job (id VARCHAR(36) PRIMARY KEY, user_id BIGINT NOT NULL, document_id VARCHAR(36), type VARCHAR(64) NOT NULL, state VARCHAR(24) NOT NULL, payload_json TEXT NOT NULL, result_json TEXT NULL, request_key VARCHAR(160) NOT NULL, retries INT NOT NULL DEFAULT 0, max_retries INT NOT NULL DEFAULT 3, next_retry_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, lease_token VARCHAR(36), lease_until TIMESTAMP NULL, error_message VARCHAR(500), row_version BIGINT NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,type,request_key));
CREATE INDEX idx_ps_job_claim ON ps_job(type,state,next_retry_at,lease_until);
CREATE TABLE ps_job_checkpoint (job_id VARCHAR(36) NOT NULL, step VARCHAR(64) NOT NULL, payload_json TEXT NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(job_id,step));
CREATE TABLE ps_outbox (id VARCHAR(36) PRIMARY KEY, job_id VARCHAR(36) NOT NULL, topic VARCHAR(128) NOT NULL, payload_json TEXT NOT NULL, state VARCHAR(16) NOT NULL DEFAULT 'PENDING', attempts INT NOT NULL DEFAULT 0, next_attempt_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(job_id,topic));
CREATE TABLE ps_consumer_receipt (event_id VARCHAR(36) PRIMARY KEY, job_id VARCHAR(36) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ps_operation_plan (id VARCHAR(36) PRIMARY KEY, type VARCHAR(64) NOT NULL, state VARCHAR(24) NOT NULL, payload_json TEXT NOT NULL, manifest_hash VARCHAR(64) NOT NULL, reason VARCHAR(500) NOT NULL, created_by BIGINT NOT NULL, approved_by BIGINT NULL, job_id VARCHAR(36), row_version BIGINT NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ps_audit_event (id VARCHAR(36) PRIMARY KEY, user_id BIGINT NOT NULL, action VARCHAR(64) NOT NULL, resource_id VARCHAR(128), reason VARCHAR(500) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_ps_audit_user_time ON ps_audit_event(user_id,created_at);
CREATE TABLE paismart_schema_history (version_no INT PRIMARY KEY, description VARCHAR(128) NOT NULL, installed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO paismart_schema_history(version_no,description) VALUES(1,'Paismart control, billing and jobs');
